<?php
declare(strict_types=1);
namespace Modules\Auxiliary;
use App\{DB,Auth,Audit};
use PDO;
final class Premises {
    public static function uuid():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-a'.substr($h,17,3).'-'.substr($h,20);}
    private static function lock(PDO $p):void{$p->query('SELECT id FROM aux_write_guard WHERE id=1 FOR UPDATE')->fetchColumn();}
    public static function save(array $input):int {
        Auth::requirePermission('premises.write');$user=Auth::user();if(!empty($user['grants_configured'])&&\App\PagePolicy::level('auxiliary.premises',$user)<2)throw new \RuntimeException('Недостаточно прав для изменения помещения.',403);foreach(['address','designation','floor','kind','area','cadastral_number','account','parent_description','parent_id','note']as $field)if(isset($input[$field])&&(!is_scalar($input[$field])||str_contains((string)$input[$field],"\0")))throw new \RuntimeException('Некорректный формат поля помещения.',422);if(isset($input['parent_id'])&&$input['parent_id']!==''&&$input['parent_id']!==null&&!preg_match('/^[1-9][0-9]{0,17}$/D',(string)$input['parent_id']))throw new \RuntimeException('Некорректная родительская карточка.',422);$id=(int)($input['id']??0);$fields=['address','designation','floor','kind','area','cadastral_number','account','parent_description','parent_id','note'];$row=[];foreach($fields as $f)$row[$f]=trim((string)($input[$f]??''));if($row['address']===''||$row['designation']===''||!in_array($row['kind'],['room','part','parking'],true))throw new \RuntimeException('Нужны адрес, обозначение и вид помещения.',422);foreach(['address'=>500,'designation'=>200,'floor'=>50,'cadastral_number'=>100,'account'=>100,'parent_description'=>500]as $f=>$limit)if(mb_strlen($row[$f])>$limit)throw new \RuntimeException('Поле превышает допустимую длину: '.$f,422);
        if($row['area']==='')$row['area']=null;elseif(!preg_match('/^\d{1,11}(?:\.\d{1,3})?$/D',$row['area'])||bccomp($row['area'],'0',3)<=0)throw new \RuntimeException('Площадь должна быть положительной, с точностью до 0,001 м².',422);else $row['area']=bcadd($row['area'],'0',3);$row['parent_id']=$row['parent_id']===''?null:(int)$row['parent_id'];$creation=(string)($input['creation_key']??'');if(!$id&&!preg_match('/^[a-f0-9-]{32,80}$/D',$creation))throw new \RuntimeException('Некорректный ключ создания карточки.',422);
        return DB::transaction(function(PDO $p)use($row,$id,$creation,$input,$fields):int {self::lock($p);$old=null;if($id){$q=$p->prepare('SELECT * FROM aux_premises WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch()?:throw new \RuntimeException('Карточка не найдена.',404);if((int)$old['revision']!==(int)($input['expected_revision']??0))throw new \RuntimeException('Карточка уже изменена. Закройте и откройте её снова, чтобы увидеть актуальные данные.',409);}else{$q=$p->prepare('SELECT * FROM aux_premises WHERE creation_key=? FOR UPDATE');$q->execute([$creation]);if($prior=$q->fetch()){foreach($fields as $f)if((string)($prior[$f]??'')!==(string)($row[$f]??''))throw new \RuntimeException('Этот запрос создания уже выполнен с другими данными.',409);return (int)$prior['id'];}}
            $identity=Workbook::identity($row['address'],$row['floor'],$row['designation'],$row['cadastral_number']);$q=$p->prepare('SELECT premise_id FROM aux_import_identities WHERE identity_key=?');$q->execute([$identity]);if(($existing=$q->fetchColumn())&&(int)$existing!==$id)throw new \RuntimeException('Помещение с теми же адресом, этажом, обозначением и кадастровой связью уже существует.',422);
            $parent=$row['parent_id'];$seen=[];while($parent!==null){if($parent===$id||isset($seen[$parent]))throw new \RuntimeException('Помещение не может входить в себя или образовывать цикл.',422);$seen[$parent]=true;$q=$p->prepare('SELECT parent_id FROM aux_premises WHERE id=? FOR UPDATE');$q->execute([$parent]);$found=$q->fetch();if(!$found)throw new \RuntimeException('Родительская карточка не найдена.',422);$parent=$found['parent_id']===null?null:(int)$found['parent_id'];}
            if($id){$set=implode(',',array_map(fn($f)=>$f.'=?',$fields));$p->prepare('UPDATE aux_premises SET '.$set.',revision=revision+1 WHERE id=?')->execute(array_merge(array_values($row),[$id]));}else{$p->prepare('INSERT INTO aux_premises('.implode(',',$fields).',creation_key) VALUES('.implode(',',array_fill(0,count($fields)+1,'?')).')')->execute(array_merge(array_values($row),[$creation]));$id=(int)$p->lastInsertId();}
            $p->prepare('INSERT IGNORE INTO aux_import_identities(identity_key,premise_id) VALUES(?,?)')->execute([$identity,$id]);Audit::record($old?'premise.update':'premise.create','premise',$id,$old,$row);return $id;
        });
    }
    public static function importWorkbook(string $source,bool $dryRun=false):array {
        $plan=Workbook::prepare(Workbook::read($source));$hash=hash_file('sha256',$source);$report=['sha256'=>$hash,'sheet'=>'Договоры аренды','parser_version'=>'1','summary'=>$plan['summary'],'issues'=>$plan['issues'],'created'=>0,'reused'=>0,'dry_run'=>$dryRun,'same_file_reimport'=>false];if($dryRun)return $report;
        $dir=APP_ROOT.'/private/auxiliary';if(!is_dir($dir))mkdir($dir,0700,true);$archive=$dir.'/'.$hash.'.xlsx';if(is_file($archive)){if(!hash_equals($hash,hash_file('sha256',$archive)))throw new \RuntimeException('Изменён неизменяемый оригинал XLSX');}else{if(!copy($source,$archive)||!hash_equals($hash,hash_file('sha256',$archive)))throw new \RuntimeException('Ошибка независимой копии XLSX');@chmod($archive,0400);}
        return DB::transaction(function(PDO $p)use($plan,$hash,$archive,$source,$report):array {self::lock($p);$q=$p->prepare('SELECT b.id,r.report_json FROM aux_import_batches b JOIN aux_import_reports r ON r.batch_id=b.id WHERE b.sha256=?');$q->execute([$hash]);if($old=$q->fetch()){$prior=json_decode($old['report_json'],true,512,JSON_THROW_ON_ERROR);$prior['created']=0;$prior['reused']=$prior['summary']['premises'];$prior['same_file_reimport']=true;return $prior;}
            $p->prepare("INSERT INTO aux_import_batches(sha256,kind,filename,archive_path) VALUES(?,'premises-xlsx',?,?)")->execute([$hash,basename($source),'private/auxiliary/'.basename($archive)]);$batch=(int)$p->lastInsertId();$mapping=[];
            foreach($plan['groups']as $g){$q=$p->prepare('SELECT p.* FROM aux_import_identities i JOIN aux_premises p ON p.id=i.premise_id WHERE i.identity_key=?');$q->execute([$g['key']]);if($old=$q->fetch()){$id=(int)$old['id'];$report['reused']++;$different=[];foreach(['area','account','address','floor','designation','cadastral_number']as $field){$a=$old[$field]??null;$b=$g[$field]??null;if($field==='area'&&$a!==null&&$b!==null&&bccomp($a,$b,3)===0)continue;if((string)$a!==(string)$b)$different[]=$field;}if($different)$report['issues'][]=['rows'=>array_column($g['rows'],'row'),'key'=>$g['key'],'reason'=>'Импорт не перезаписал существующую карточку. Различаются: '.implode(', ',$different),'incoming'=>array_intersect_key($g,array_flip($different))];}
                else{$fields=['address','designation','floor','kind','area','cadastral_number','account','parent_description','note'];$values=array_map(fn($f)=>$g[$f],$fields);$p->prepare('INSERT INTO aux_premises('.implode(',',$fields).',creation_key,area_variants,account_variants) VALUES('.implode(',',array_fill(0,count($fields)+3,'?')).')')->execute(array_merge($values,['import-'.$g['key'],json_encode($g['area_variants'],JSON_THROW_ON_ERROR),json_encode($g['account_variants'],JSON_THROW_ON_ERROR)]));$id=(int)$p->lastInsertId();$p->prepare('INSERT INTO aux_import_identities(identity_key,premise_id) VALUES(?,?)')->execute([$g['key'],$id]);$report['created']++;}$mapping[$g['key']]=$id;
            }
            foreach($plan['rows']as $r){$p->prepare('INSERT INTO aux_source_rows(batch_id,source_row_number,hidden,raw_evidence,reason) VALUES(?,?,?,?,?)')->execute([$batch,$r['row'],(int)$r['hidden'],json_encode($r,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$r['reason']??null]);$rowId=(int)$p->lastInsertId();foreach($r['keys']??[]as $key)$p->prepare('INSERT INTO aux_premise_source_links(source_row_id,premise_id) VALUES(?,?)')->execute([$rowId,$mapping[$key]]);}
            foreach($report['issues']as $i=>$issue)$p->prepare("INSERT INTO aux_issues(identity_key,category,title,detail,evidence) VALUES(?,'premises-import',?,?,?)")->execute([hash('sha256',$hash.'|'.$i),'Проверка технического реестра',$issue['reason'],json_encode(['batch_id'=>$batch]+$issue,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$report['summary']['issue_groups']=count($report['issues']);$p->prepare('INSERT INTO aux_import_reports(batch_id,parser_version,sheet,report_json) VALUES(?,?,?,?)')->execute([$batch,'1','Договоры аренды',json_encode($report,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);return $report;
        });
    }
}
